INSERT OR REPLACE INTO milestones(object_id,milestone_key,milestone_id,canonical_id,group_name,name,summary,nature,domain,status,confidence,introduced_date,introduced_commit,tag,notes,source_file,source_row) VALUES('milestone:0493x11a','0493x11a','x11a','0493x11a','x11 : validation quantitative capillaire','Qualification Young–Laplace quantitative','Mesure sur gouttes statiques multi-rayons/multi-sigma la loi de Laplace avec la pression Q6 résolue x9e; la lecture finale utilise les baselines sigma=0 appariées consolidées par x11c.','QUALIFICATION','SURFACE_TENSION','Qualification historique quantitative; base de la calibration mécanique x12yl','A','2026-08-22','8f587696bac0f48a813025e5cb364603ba6cfeba',NULL,'Curation V4.19 fondée sur les runners/analyseurs x11/x12, les README de calibrateurs, le code courant audité et les preuves Git multi-ref. x11a/b/c n’ajoutent aucune force; x12a est la seule nouvelle physique runtime x12; x12b/c/d/cal/yl sont orchestration/benchmark/calibration.','run_0493x11a_young_laplace_validation.sh',NULL);
INSERT OR REPLACE INTO milestones(object_id,milestone_key,milestone_id,canonical_id,group_name,name,summary,nature,domain,status,confidence,introduced_date,introduced_commit,tag,notes,source_file,source_row) VALUES('milestone:0493x11b','0493x11b','x11b','0493x11b','x11 : validation quantitative capillaire','Qualification de dispersion des ondes capillaires','Excite des interfaces sinusoïdales résolues, suit les modes de Fourier et ajuste leur oscillation amortie pour comparer omega_num à la dispersion capillaire théorique.','QUALIFICATION','SURFACE_TENSION','Qualification dynamique historique; base méthodologique du calibrateur x12cal','A','2026-08-22','8f587696bac0f48a813025e5cb364603ba6cfeba',NULL,'Curation V4.19 fondée sur les runners/analyseurs x11/x12, les README de calibrateurs, le code courant audité et les preuves Git multi-ref. x11a/b/c n’ajoutent aucune force; x12a est la seule nouvelle physique runtime x12; x12b/c/d/cal/yl sont orchestration/benchmark/calibration.','run_0493x11b_capillary_wave_validation.sh',NULL);
INSERT OR REPLACE INTO milestones(object_id,milestone_key,milestone_id,canonical_id,group_name,name,summary,nature,domain,status,confidence,introduced_date,introduced_commit,tag,notes,source_file,source_row) VALUES('milestone:0493x11c','0493x11c','x11c','0493x11c','x11 : validation quantitative capillaire','Correction de protocole capillaire et baseline sigma=0','Corrige l’analyse x11 sans nouvelle force: Young–Laplace utilise p(sigma)-p(0), les ondes sont refittées sur la fenêtre précoce haut-SNR, et le support p3/x9e peut être construit à cadence diagnostic pour sigma=0 sans appliquer de potentiel capillaire.','DIAGNOSTIC','SURFACE_TENSION','Correction analyse/protocole et support observation-only; aucune nouvelle physique capillaire','A','2026-08-22','8f587696bac0f48a813025e5cb364603ba6cfeba',NULL,'Curation V4.19 fondée sur les runners/analyseurs x11/x12, les README de calibrateurs, le code courant audité et les preuves Git multi-ref. x11a/b/c n’ajoutent aucune force; x12a est la seule nouvelle physique runtime x12; x12b/c/d/cal/yl sont orchestration/benchmark/calibration.','README_0493x11c_REFINED_CAPILLARY_ANALYSIS.md',NULL);
INSERT OR REPLACE INTO milestones(object_id,milestone_key,milestone_id,canonical_id,group_name,name,summary,nature,domain,status,confidence,introduced_date,introduced_commit,tag,notes,source_file,source_row) VALUES('milestone:0493x12a','0493x12a','x12a','0493x12a','x12 : refroidissement local, benchmarks et calibrateurs','Refroidissement thermique local des petites structures','Ajoute la seule nouvelle physique runtime x12: fT=min(1,(Lloc/Rc)^2), où Lloc est la demi-distance à l’interface alpha=0.5 opposée le long de la normale Q2 intérieure; fT réduit localement l’enveloppe cinétique x10o et la cible thermostat.','CODE','FREE_SURFACE_KINETICS','Actif dans la chaîne liquide qualifiée; exclusif avec le limiter x10w','A','2026-08-26','5fea55644b841a0bd0c04ad8be908d04b3bbd6b6',NULL,'Curation V4.19 fondée sur les runners/analyseurs x11/x12, les README de calibrateurs, le code courant audité et les preuves Git multi-ref. x11a/b/c n’ajoutent aucune force; x12a est la seule nouvelle physique runtime x12; x12b/c/d/cal/yl sont orchestration/benchmark/calibration.','run_0493x12a_local_thermal_cooling_validation.sh',NULL);
INSERT OR REPLACE INTO milestones(object_id,milestone_key,milestone_id,canonical_id,group_name,name,summary,nature,domain,status,confidence,introduced_date,introduced_commit,tag,notes,source_file,source_row) VALUES('milestone:0493x12b','0493x12b','x12b','0493x12b','x12 : refroidissement local, benchmarks et calibrateurs','Prototype JFM D=320h sur obstacle Darcy/chi','Construit un cas splash 2-D à goutte D=320h et marche obstacle Darcy/chi avec la chaîne x10v+x12a; il fixe une géométrie JFM-scaled mais se déclare encore exploratoire, sans nouvelle physique C++.','BENCHMARK','FREE_SURFACE_KINETICS','Benchmark exploratoire de construction; pas encore une reproduction quantitative JFM 524','A','2026-08-26','5fea55644b841a0bd0c04ad8be908d04b3bbd6b6',NULL,'Curation V4.19 fondée sur les runners/analyseurs x11/x12, les README de calibrateurs, le code courant audité et les preuves Git multi-ref. x11a/b/c n’ajoutent aucune force; x12a est la seule nouvelle physique runtime x12; x12b/c/d/cal/yl sont orchestration/benchmark/calibration.','run_0493x12b_obstacle_JFM_D320_Re649_We514.sh',NULL);
INSERT OR REPLACE INTO milestones(object_id,milestone_key,milestone_id,canonical_id,group_name,name,summary,nature,domain,status,confidence,introduced_date,introduced_commit,tag,notes,source_file,source_row) VALUES('milestone:0493x12c','0493x12c','x12c','0493x12c','x12 : refroidissement local, benchmarks et calibrateurs','Benchmark JFM compact-Y à physique inchangée','Réduit le domaine vertical inutilisé du cas x12b en conservant h et la même chaîne physique, afin de rendre la campagne obstacle/splash plus exploitable sans modifier le solveur.','BENCHMARK','FREE_SURFACE_KINETICS','Étape de production/compaction du benchmark; physique identique à x12b','A','2026-08-26','5fea55644b841a0bd0c04ad8be908d04b3bbd6b6',NULL,'Curation V4.19 fondée sur les runners/analyseurs x11/x12, les README de calibrateurs, le code courant audité et les preuves Git multi-ref. x11a/b/c n’ajoutent aucune force; x12a est la seule nouvelle physique runtime x12; x12b/c/d/cal/yl sont orchestration/benchmark/calibration.','run_0493x12c_obstacle_JFM_D320_Re649_We514_compactY.sh',NULL);
INSERT OR REPLACE INTO milestones(object_id,milestone_key,milestone_id,canonical_id,group_name,name,summary,nature,domain,status,confidence,introduced_date,introduced_commit,tag,notes,source_file,source_row) VALUES('milestone:0493x12d','0493x12d','x12d','0493x12d','x12 : refroidissement local, benchmarks et calibrateurs','Cas de mesure JFM 524 à géométrie/We/Fr ciblés','Verrouille le cas de mesure obstacle JFM 524 avec géométrie et We/Fr proches de l’article, sur la chaîne x10o+CIC+Q2+x10p/q+x10u/v+x12a; l’écart de Reynolds du fluide numérique reste explicitement déclaré.','BENCHMARK','FREE_SURFACE_KINETICS','Benchmark applicatif de mesure; géométrie/We/Fr ciblés mais Re numérique ~649 au lieu de Re expérimental 12200','A','2026-08-26','5fea55644b841a0bd0c04ad8be908d04b3bbd6b6',NULL,'Curation V4.19 fondée sur les runners/analyseurs x11/x12, les README de calibrateurs, le code courant audité et les preuves Git multi-ref. x11a/b/c n’ajoutent aucune force; x12a est la seule nouvelle physique runtime x12; x12b/c/d/cal/yl sont orchestration/benchmark/calibration.','run_0493x12d_jfm524_measurement_case.sh',NULL);
INSERT OR REPLACE INTO milestones(object_id,milestone_key,milestone_id,canonical_id,group_name,name,summary,nature,domain,status,confidence,introduced_date,introduced_commit,tag,notes,source_file,source_row) VALUES('milestone:0493x12cal','0493x12cal','x12cal','0493x12cal','x12 : refroidissement local, benchmarks et calibrateurs','Calibrateur dynamique de tension superficielle','Mesure sigma_eff dynamique par dispersion omega^2=(sigma/rho) k^3 tanh(kH) sur plusieurs modes/réalisations, avec politique PASS/REVIEW/INVALID; la propriété dynamique reste distincte de la calibration mécanique x12yl.','CALIBRATOR','SURFACE_TENSION','Calibrateur dynamique courant; aucune nouvelle physique C++','A','2026-08-26','5fea55644b841a0bd0c04ad8be908d04b3bbd6b6',NULL,'Curation V4.19 fondée sur les runners/analyseurs x11/x12, les README de calibrateurs, le code courant audité et les preuves Git multi-ref. x11a/b/c n’ajoutent aucune force; x12a est la seule nouvelle physique runtime x12; x12b/c/d/cal/yl sont orchestration/benchmark/calibration.','README_0493X12CAL_CAPILLARY_CALIBRATOR.md',NULL);
INSERT OR REPLACE INTO milestones(object_id,milestone_key,milestone_id,canonical_id,group_name,name,summary,nature,domain,status,confidence,introduced_date,introduced_commit,tag,notes,source_file,source_row) VALUES('milestone:0493x12yl','0493x12yl','x12yl','0493x12yl','x12 : refroidissement local, benchmarks et calibrateurs','Calibrateur mécanique/statique de tension superficielle','Mesure sigma_eff mécanique par paires sigma/sigma0 sur gouttes résolues: dp_cap=p(sigma)-p(0)=sigma_eff<kappa>_active, en utilisant la courbure active mesurée et une politique explicite PASS/REVIEW/INVALID.','CALIBRATOR','SURFACE_TENSION','Calibrateur mécanique/statique courant; remplace x11a comme extraction scalaire de sigma_eff','A','2026-08-26','5fea55644b841a0bd0c04ad8be908d04b3bbd6b6',NULL,'Curation V4.19 fondée sur les runners/analyseurs x11/x12, les README de calibrateurs, le code courant audité et les preuves Git multi-ref. x11a/b/c n’ajoutent aucune force; x12a est la seule nouvelle physique runtime x12; x12b/c/d/cal/yl sont orchestration/benchmark/calibration.','README_0493X12YL_YOUNG_LAPLACE_CALIBRATOR.md',NULL);
